package com.magraoxx.eichattv;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.media.AudioManager;import android.os.*;import android.speech.*;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 private static final int REQ_MIC=1001;private TextView status,caption,micText;private Button listen,account;private TextToSpeech tts;private CommandEngine engine;private OpenAiClient ai;private ChatGptAuth auth;private SpeechRecognizer speech;private boolean pending,audioRetry;
 public void onCreate(Bundle b){super.onCreate(b);engine=new CommandEngine(this);ai=new OpenAiClient(this);auth=new ChatGptAuth(this);buildUi();refreshAccount();tts=new TextToSpeech(this,x->{if(x==0){tts.setLanguage(new Locale("pt","BR"));tts.setSpeechRate(1.02f);}});if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);if(getIntent()!=null&&getIntent().getBooleanExtra("start_listening",false))startListening();}
 private TextView text(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);return v;}
 private GradientDrawable shape(int fill,float radius,int stroke){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(radius);if(stroke!=0)g.setStroke(5,stroke);return g;}
 private void paintButton(Button b,int color,boolean focused){b.setBackground(shape(focused?lighten(color):color,18,focused?Color.WHITE:0));b.setScaleX(focused?1.035f:1f);b.setScaleY(focused?1.08f:1f);b.setElevation(focused?14f:2f);}
 private int lighten(int c){return Color.rgb(Math.min(255,Color.red(c)+38),Math.min(255,Color.green(c)+38),Math.min(255,Color.blue(c)+38));}
 private Button button(String s,int color,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(17);b.setTextColor(Color.WHITE);b.setTypeface(null,1);b.setGravity(Gravity.CENTER);b.setPadding(18,0,18,0);b.setMinHeight(64);b.setFocusable(true);b.setFocusableInTouchMode(true);b.setClickable(true);b.setOnClickListener(l);paintButton(b,color,false);b.setOnFocusChangeListener((v,f)->paintButton((Button)v,color,f));return b;}
 private void buildUi(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(12,14,18));LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setGravity(Gravity.CENTER_HORIZONTAL);center.setPadding(32,70,32,60);scroll.addView(center,new ScrollView.LayoutParams(-1,-1));TextView logo=text("Ei Chat",42);logo.setGravity(Gravity.CENTER);logo.setTypeface(null,1);center.addView(logo,new LinearLayout.LayoutParams(-1,-2));caption=text("Assistente com IA",19);caption.setGravity(Gravity.CENTER);caption.setTextColor(Color.LTGRAY);center.addView(caption,new LinearLayout.LayoutParams(-1,-2));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(28,25,28,25);card.setBackground(shape(Color.rgb(31,35,43),28,0));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,30,0,24);center.addView(card,cp);status=text("Conecte sua conta ChatGPT para começar",25);status.setGravity(Gravity.CENTER);card.addView(status,new LinearLayout.LayoutParams(-1,-2));micText=text("● aguardando conexão",16);micText.setGravity(Gravity.CENTER);micText.setPadding(0,14,0,2);card.addView(micText,new LinearLayout.LayoutParams(-1,-2));account=button("CONECTAR CHATGPT",Color.rgb(25,120,210),v->connectChatGpt());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,72);ap.setMargins(10,0,10,14);center.addView(account,ap);listen=button("🎤  OUVIR COM IA",Color.rgb(25,150,95),v->{audioRetry=false;startListening();});LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,72);bp.setMargins(10,0,10,14);center.addView(listen,bp);Button test=button("TESTAR IA",Color.rgb(85,80,170),v->testAi());LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,64);tp.setMargins(10,0,10,14);center.addView(test,tp);Button diag=button("DIAGNÓSTICO",Color.rgb(70,76,88),v->{caption.setText("Diagnóstico");status.setText(TvMicrophone.report(this)+"\nReconhecimento: "+(SpeechRecognizer.isRecognitionAvailable(this)?"disponível":"indisponível")+"\nChatGPT: "+auth.accountLabel());});LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,64);dp.setMargins(10,0,10,0);center.addView(diag,dp);setContentView(scroll);account.setNextFocusDownId(listen.getId());new Handler(Looper.getMainLooper()).postDelayed(()->{if(account.isEnabled())account.requestFocus();else listen.requestFocus();},250);}
 private void refreshAccount(){boolean ok=auth.isConnected();account.setText(ok?"✓ CHATGPT CONECTADO":"CONECTAR CHATGPT");listen.setEnabled(ok);listen.setAlpha(ok?1f:.45f);if(ok){caption.setText("Assistente com IA");status.setText("Pressione OUVIR COM IA e fale normalmente");micText.setText("● IA pronta • "+auth.accountLabel());}else{status.setText("Conecte sua conta ChatGPT para usar a IA");micText.setText("● aguardando conexão");}}
 private void connectChatGpt(){caption.setText("Conectando ao ChatGPT");status.setText("Abrindo o login…\nAutorize no navegador e volte ao Ei Chat.");account.setEnabled(false);auth.signIn(new ChatGptAuth.Callback(){public void onSuccess(String m){runOnUiThread(()->{account.setEnabled(true);refreshAccount();status.setText(m+"\nAgora selecione OUVIR COM IA.");listen.requestFocus();});}public void onError(String e){runOnUiThread(()->{account.setEnabled(true);caption.setText("Ei Chat");status.setText(e);micText.setText("● conexão necessária");account.requestFocus();});}});}
 private void startListening(){if(!auth.isConnected()){connectChatGpt();return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pending=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);return;}if(!SpeechRecognizer.isRecognitionAvailable(this)){caption.setText("Ei Chat • voz indisponível");status.setText("Esta TV não disponibilizou um serviço de reconhecimento de voz para aplicativos.");return;}if(tts!=null)tts.stop();AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);if(am!=null){try{am.setMode(AudioManager.MODE_NORMAL);am.setSpeakerphoneOn(false);}catch(Throwable ignored){}}destroySpeech();speech=SpeechRecognizer.createSpeechRecognizer(this);speech.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle p){audioRetry=false;caption.setText("Ei Chat • ouvindo");status.setText("Pode falar…");micText.setText("● microfone ativo");}public void onBeginningOfSpeech(){}public void onRmsChanged(float r){micText.setText(r>2?"● ouvindo sua voz":"● microfone ativo");}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){caption.setText("Ei Chat • entendendo");status.setText("Entendendo sua voz…");}public void onError(int e){if(e==SpeechRecognizer.ERROR_AUDIO&&!audioRetry){audioRetry=true;caption.setText("Ei Chat • ajustando áudio");status.setText("Reabrindo o microfone da TV…");micText.setText("● segunda tentativa automática");destroySpeech();new Handler(Looper.getMainLooper()).postDelayed(()->startListening(),650);return;}caption.setText("Ei Chat • erro de voz");status.setText("Reconhecimento de voz: "+speechError(e)+"\nAbra DIAGNÓSTICO se continuar.");micText.setText("● tente novamente");}public void onResults(Bundle b){ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a==null||a.isEmpty()||a.get(0).trim().isEmpty()){onError(SpeechRecognizer.ERROR_NO_MATCH);return;}handle(a.get(0).trim());}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"pt-BR");i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_PREFERENCE,"pt-BR");i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,3);i.putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,false);try{speech.startListening(i);}catch(Throwable e){caption.setText("Ei Chat • erro de voz");status.setText("Não foi possível iniciar o microfone: "+e.getMessage());}}
 private void destroySpeech(){if(speech!=null){try{speech.cancel();}catch(Throwable ignored){}try{speech.destroy();}catch(Throwable ignored){}speech=null;}}
 private void testAi(){if(!auth.isConnected()){connectChatGpt();return;}caption.setText("Ei Chat • teste da IA");status.setText("Testando conexão e resposta…");ai.ask("Responda exatamente: Ei Chat conectado e funcionando.",new OpenAiClient.Callback(){public void onSuccess(String x){runOnUiThread(()->{caption.setText("Teste da IA concluído");status.setText(x);speak(x);});}public void onError(String x){runOnUiThread(()->{caption.setText("Teste da IA falhou");status.setText(x);});}});}
 private void handle(String q){caption.setText("Você disse");status.setText("“"+q+"”");CommandEngine.Result r=engine.execute(q);if(r.handled){caption.setText("Ei Chat");status.setText(r.message);speak(r.message);return;}caption.setText("Ei Chat • pensando com IA");status.setText("Pensando…");ai.ask(q,new OpenAiClient.Callback(){public void onSuccess(String x){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(x);speak(x);});}public void onError(String x){runOnUiThread(()->{caption.setText("Ei Chat • erro da IA");status.setText(x);});}});}
 private static String speechError(int e){switch(e){case SpeechRecognizer.ERROR_AUDIO:return "erro de áudio da TV";case SpeechRecognizer.ERROR_CLIENT:return "erro do cliente";case SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS:return "sem permissão de microfone";case SpeechRecognizer.ERROR_NETWORK:return "erro de rede";case SpeechRecognizer.ERROR_NETWORK_TIMEOUT:return "tempo de rede esgotado";case SpeechRecognizer.ERROR_NO_MATCH:return "não entendi a fala";case SpeechRecognizer.ERROR_RECOGNIZER_BUSY:return "reconhecedor ocupado";case SpeechRecognizer.ERROR_SERVER:return "erro do serviço de voz";case SpeechRecognizer.ERROR_SPEECH_TIMEOUT:return "nenhuma fala detectada";default:return "código "+e;}}
 private void speak(String x){if(tts!=null&&x!=null&&!x.trim().isEmpty())tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"ei_chat");}
 public void onRequestPermissionsResult(int c,String[]p,int[]g){super.onRequestPermissionsResult(c,p,g);if(c==REQ_MIC&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&pending){pending=false;startListening();}}protected void onResume(){super.onResume();if(auth!=null)refreshAccount();}protected void onDestroy(){destroySpeech();if(tts!=null)tts.shutdown();super.onDestroy();}
}
